ALTER TABLE public.user_module_permissions DROP CONSTRAINT user_module_permissions_module_key_check;
ALTER TABLE public.user_module_permissions ADD CONSTRAINT user_module_permissions_module_key_check CHECK (module_key IN ('orders','inventory','daybook','customer_ledger','income_expenses'));
CREATE TABLE public.income_expense_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, type text NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.income_expense_categories TO authenticated; GRANT ALL ON public.income_expense_categories TO service_role;
ALTER TABLE public.income_expense_categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY categories_view ON public.income_expense_categories FOR SELECT TO authenticated USING (public.has_module_perm(auth.uid(),'income_expenses','view'));
CREATE POLICY categories_add ON public.income_expense_categories FOR INSERT TO authenticated WITH CHECK (public.has_module_perm(auth.uid(),'income_expenses','add'));
CREATE POLICY categories_edit ON public.income_expense_categories FOR UPDATE TO authenticated USING (public.has_module_perm(auth.uid(),'income_expenses','edit')) WITH CHECK (public.has_module_perm(auth.uid(),'income_expenses','edit'));
CREATE POLICY categories_delete ON public.income_expense_categories FOR DELETE TO authenticated USING (public.is_admin(auth.uid()));
CREATE UNIQUE INDEX income_expense_category_name ON public.income_expense_categories(type,lower(name));
CREATE TABLE public.income_expense_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_type text NOT NULL, payment_date date NOT NULL, amount numeric(14,2) NOT NULL, category_id uuid NOT NULL REFERENCES public.income_expense_categories(id) ON DELETE RESTRICT, payment_mode text, note text, created_by uuid, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.income_expense_transactions TO authenticated; GRANT ALL ON public.income_expense_transactions TO service_role;
ALTER TABLE public.income_expense_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY transactions_view ON public.income_expense_transactions FOR SELECT TO authenticated USING (public.has_module_perm(auth.uid(),'income_expenses','view'));
CREATE POLICY transactions_add ON public.income_expense_transactions FOR INSERT TO authenticated WITH CHECK (public.has_module_perm(auth.uid(),'income_expenses','add'));
CREATE POLICY transactions_edit ON public.income_expense_transactions FOR UPDATE TO authenticated USING (public.has_module_perm(auth.uid(),'income_expenses','edit')) WITH CHECK (public.has_module_perm(auth.uid(),'income_expenses','edit'));
CREATE POLICY transactions_delete ON public.income_expense_transactions FOR DELETE TO authenticated USING (public.is_admin(auth.uid()));
CREATE INDEX income_expense_date ON public.income_expense_transactions(payment_date DESC,created_at DESC,id);
CREATE INDEX income_expense_category ON public.income_expense_transactions(category_id);
CREATE TABLE public.income_expense_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_id uuid NOT NULL, previous_values jsonb NOT NULL, deleted_by uuid, deleted_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.income_expense_audit TO authenticated; GRANT ALL ON public.income_expense_audit TO service_role;
ALTER TABLE public.income_expense_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_admin_view ON public.income_expense_audit FOR SELECT TO authenticated USING (public.is_admin(auth.uid()));
CREATE FUNCTION public.validate_income_expense_category() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.name := regexp_replace(btrim(NEW.name),'\s+',' ','g'); IF NEW.name='' OR NEW.type NOT IN ('income','expense') THEN RAISE EXCEPTION 'Valid category name and type required'; END IF; IF TG_OP='UPDATE' AND NEW.type<>OLD.type THEN RAISE EXCEPTION 'Category type cannot be changed'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER validate_category BEFORE INSERT OR UPDATE ON public.income_expense_categories FOR EACH ROW EXECUTE FUNCTION public.validate_income_expense_category();
CREATE FUNCTION public.validate_income_expense_transaction() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE cat public.income_expense_categories; BEGIN IF NEW.amount<=0 OR NEW.amount::text IN ('NaN','Infinity','-Infinity') OR NEW.transaction_type NOT IN ('income','expense') THEN RAISE EXCEPTION 'Positive amount and valid transaction type required'; END IF; SELECT * INTO cat FROM public.income_expense_categories WHERE id=NEW.category_id; IF NOT FOUND OR cat.type<>NEW.transaction_type THEN RAISE EXCEPTION 'Category must match transaction type'; END IF; IF TG_OP='INSERT' THEN IF NOT cat.is_active THEN RAISE EXCEPTION 'Choose an active category'; END IF; NEW.created_by:=auth.uid(); ELSE IF (NEW.category_id<>OLD.category_id OR NEW.transaction_type<>OLD.transaction_type) AND NOT cat.is_active THEN RAISE EXCEPTION 'Choose an active category'; END IF; NEW.id:=OLD.id; NEW.created_by:=OLD.created_by; NEW.created_at:=OLD.created_at; END IF; NEW.updated_by:=auth.uid(); NEW.updated_at:=now(); NEW.payment_mode:=nullif(btrim(NEW.payment_mode),''); NEW.note:=nullif(btrim(NEW.note),''); RETURN NEW; END $$;
CREATE TRIGGER validate_transaction BEFORE INSERT OR UPDATE ON public.income_expense_transactions FOR EACH ROW EXECUTE FUNCTION public.validate_income_expense_transaction();
CREATE FUNCTION public.audit_income_expense_delete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.income_expense_audit(transaction_id,previous_values,deleted_by) VALUES(OLD.id,to_jsonb(OLD),auth.uid()); RETURN OLD; END $$;
REVOKE ALL ON FUNCTION public.audit_income_expense_delete() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER audit_transaction_delete AFTER DELETE ON public.income_expense_transactions FOR EACH ROW EXECUTE FUNCTION public.audit_income_expense_delete();
CREATE FUNCTION public.admin_income_expense_summary(date_from date DEFAULT NULL,date_to date DEFAULT NULL,type_filter text DEFAULT NULL,category_ids uuid[] DEFAULT NULL,search_text text DEFAULT '') RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF auth.uid() IS NULL OR NOT public.is_admin(auth.uid()) THEN RAISE EXCEPTION 'Admin access required' USING ERRCODE='42501'; END IF; SELECT jsonb_build_object('totalIncome',coalesce(sum(t.amount) FILTER(WHERE t.transaction_type='income'),0),'totalExpenses',coalesce(sum(t.amount) FILTER(WHERE t.transaction_type='expense'),0),'netCashFlow',coalesce(sum(CASE WHEN t.transaction_type='income' THEN t.amount ELSE -t.amount END),0)) INTO result FROM public.income_expense_transactions t JOIN public.income_expense_categories c ON c.id=t.category_id WHERE (date_from IS NULL OR t.payment_date>=date_from) AND (date_to IS NULL OR t.payment_date<=date_to) AND (type_filter IS NULL OR t.transaction_type=type_filter) AND (category_ids IS NULL OR t.category_id=ANY(category_ids)) AND (search_text='' OR strpos(lower(concat_ws(' ',c.name,t.note,t.payment_mode,t.transaction_type)),lower(btrim(search_text)))>0); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.admin_income_expense_summary(date,date,text,uuid[],text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_income_expense_summary(date,date,text,uuid[],text) TO authenticated;
INSERT INTO public.income_expense_categories(name,type) VALUES ('Staff Salary','expense'),('Labour Charges','expense'),('Freight / Transportation','expense'),('Fuel / Petrol','expense'),('Vendor Payments','expense'),('Repairs & Maintenance','expense'),('Office Expenses','expense'),('Electricity & Utilities','expense'),('Rent','expense'),('Miscellaneous Expenses','expense'),('Customer Payments','income'),('Other Business Income','income'),('Refunds Received','income'),('Miscellaneous Income','income');